<script setup lang="ts">
import { useAccessStore } from '../stores/access';
const access=useAccessStore();
import { onMounted,onUnmounted,ref,watch } from 'vue';
interface GitFile{path:string;status:string;sha256:string|null;eligible:boolean;reason?:string;patch?:string}
interface Status{initialized:boolean;root:string;head:string|null;branch:string;branches:string[];remote:string;files:GitFile[];identity:{name:string;email:string}}
const props=defineProps<{projectId:string;disabled?:boolean}>(),emit=defineEmits<{busy:[value:boolean]}>();
const state=ref<Status|null>(null),busy=ref(false),error=ref(''),message=ref(''),selected=ref<string[]>([]),name=ref(''),email=ref(''),commitMessage=ref(''),branch=ref(''),remote=ref(''),base=ref('main'),title=ref(''),body=ref(''),confirmed=ref(false),pr=ref('');
let disposed=false;
watch(busy,value=>emit('busy',value));onUnmounted(()=>{disposed=true;emit('busy',false);});
async function request<T>(suffix='',input?:unknown):Promise<T>{const response=await fetch(`/api/projects/${encodeURIComponent(props.projectId)}/git${suffix}`,input===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error?.message??'Git no completó la operación.');return result as T;}
async function refresh(){const target=props.projectId;try{const result=await request<Status>();if(disposed||target!==props.projectId)return;state.value=result;selected.value=[];remote.value=result.remote;if(!name.value)name.value=result.identity.name;if(!email.value)email.value=result.identity.email;confirmed.value=false;}catch(cause){if(!disposed)error.value=(cause as Error).message;}}
async function act(action:'init'|'branch'|'remote'|'commit'|'publish',create=false){if(!state.value)return;busy.value=true;error.value='';message.value='';const target=props.projectId;
 try{const input=action==='init'?{}:action==='branch'?{name:branch.value,create,head:state.value.head}:action==='remote'?{url:remote.value,expectedRemote:state.value.remote}:action==='commit'?{head:state.value.head,message:commitMessage.value,name:name.value,email:email.value,files:state.value.files.filter(file=>selected.value.includes(file.path)).map(({path,sha256})=>({path,sha256}))}:{head:state.value.head,remote:state.value.remote,base:base.value,title:title.value,body:body.value,confirmed:confirmed.value};
 const result=await request<{commit?:string;warning?:string;url?:string}>('/'+action,input);if(disposed||target!==props.projectId)return;if(result.url&&/^https:\/\/github\.com\/[^/]+\/[^/]+\/pull\/\d+$/.test(result.url))pr.value=result.url;message.value=result.warning??(result.commit?`Commit local creado: ${result.commit}`:action==='publish'?'Rama publicada y PR borrador confirmado.':'Estado Git actualizado.');await refresh();
 }catch(cause){if(!disposed)error.value=(cause as Error).message;}finally{busy.value=false;}}
watch(()=>props.projectId,()=>{state.value=null;selected.value=[];name.value='';email.value='';pr.value='';message.value='';error.value='';void refresh();});onMounted(()=>{void refresh();});
</script>
<template>
 <section class="git-panel" aria-label="Control de versiones"><div class="result-toolbar"><h3>Git y publicación</h3><button class="connection-action" :disabled="busy||disabled" @click="refresh">Actualizar Git</button></div><p v-if="error" class="library-error" role="alert">{{ error }}</p><p v-if="message" class="result-note" role="status">{{ message }}</p><p v-if="busy" role="status">Operación Git en curso…</p>
 <template v-if="state"><p class="source-hash">{{ state.root }}<br/>{{ state.initialized?`Rama: ${state.branch||'HEAD separado'} · Commit: ${state.head||'Sin commits'}`:'Esta carpeta todavía no tiene un repositorio Git propio.' }}</p>
 <button v-if="!state.initialized" class="connection-action" :disabled="!access.canWrite||busy||disabled" @click="act('init')">Iniciar Git local en esta carpeta</button>
 <template v-else>
 <details open><summary>Cambios para el commit</summary><p class="result-note">Revisa los diffs y selecciona archivos. El commit usa el contenido mostrado y conserva los archivos que otras herramientas hayan preparado en el índice. Los hooks y filtros Git no se ejecutan.</p>
 <article v-for="file in state.files" :key="file.path" class="git-file"><label><input v-model="selected" type="checkbox" :value="file.path" :disabled="!access.canWrite||busy||disabled||!file.eligible"/><code>{{ file.status }} {{ file.path }}</code></label><p v-if="file.reason" class="result-note">{{ file.reason }}</p><details v-if="file.patch"><summary>Ver diff de {{ file.path }}</summary><pre>{{ file.patch }}</pre></details></article><p v-if="!state.files.length" class="result-note">No hay cambios pendientes.</p>
 <form class="git-form" @submit.prevent="act('commit')"><label for="git-name">Nombre del autor</label><input id="git-name" v-model="name" maxlength="100" :disabled="!access.canWrite||busy||disabled"/><label for="git-email">Correo del autor</label><input id="git-email" v-model="email" type="email" maxlength="200" :disabled="!access.canWrite||busy||disabled"/><label for="git-message">Mensaje del commit</label><textarea id="git-message" v-model="commitMessage" maxlength="2000" rows="2" :disabled="!access.canWrite||busy||disabled"/><button class="primary-button" :disabled="!access.canWrite||busy||disabled||!selected.length||!name.trim()||!email.trim()||!commitMessage.trim()">Crear commit local de {{ selected.length }} archivos</button></form></details>
 <details><summary>Ramas</summary><p class="result-note">Ramas locales: {{ state.branches.join(', ')||'Sin commits' }}. Cambiar de rama requiere una carpeta sin cambios pendientes.</p><form class="git-form" @submit.prevent="act('branch',true)"><label for="git-branch">Nombre de rama</label><input id="git-branch" v-model="branch" maxlength="100" placeholder="feature/mejora" :disabled="!access.canWrite||busy||disabled"/><div class="source-actions"><button class="connection-action" :disabled="!access.canWrite||busy||disabled||!branch.trim()||!!state.files.length">Crear rama y cambiar</button><button class="connection-action" type="button" :disabled="!access.canWrite||busy||disabled||!state.branches.includes(branch)||!!state.files.length" @click="act('branch',false)">Cambiar a rama existente</button></div></form></details>
 <details><summary>Remoto y pull request</summary><p class="result-note">Conecta un repositorio GitHub existente. Configurar el remoto solo guarda su dirección. Publicar enviará la rama y su historial al repositorio indicado y creará un PR borrador. Requiere GitHub CLI autenticado con <code>gh auth login</code>.</p>
 <form v-if="access.admin" class="git-form" @submit.prevent="act('remote')"><label for="git-remote">URL HTTPS del repositorio GitHub</label><input id="git-remote" v-model="remote" maxlength="1000" placeholder="https://github.com/usuario/proyecto.git" :disabled="!access.canWrite||busy||disabled"/><p class="source-hash">Remoto actual: {{ state.remote||'Sin remoto' }}</p><button class="connection-action" :disabled="!access.canWrite||busy||disabled||!remote.trim()">Guardar remoto origin</button></form>
 <form v-if="access.admin" class="git-form" @submit.prevent="act('publish')"><label for="git-base">Rama destino del PR</label><input id="git-base" v-model="base" maxlength="100" :disabled="!access.canWrite||busy||disabled"/><label for="git-title">Título del PR</label><input id="git-title" v-model="title" maxlength="200" :disabled="!access.canWrite||busy||disabled"/><label for="git-body">Descripción del PR</label><textarea id="git-body" v-model="body" maxlength="20000" rows="5" :disabled="!access.canWrite||busy||disabled"/><label class="git-confirm"><input v-model="confirmed" type="checkbox" :disabled="!access.canWrite||busy||disabled"/>Confirmo enviar {{ state.branch }} y su historial a {{ state.remote }} y crear el PR borrador hacia {{ base }}.</label><button class="primary-button" :disabled="!access.canWrite||busy||disabled||!confirmed||!state.remote||!state.head||!title.trim()||!!state.files.length||['main','master',base].includes(state.branch)">Publicar rama y crear PR borrador</button></form><p v-if="pr"><a :href="pr" target="_blank" rel="noopener noreferrer">Abrir pull request</a></p></details>
 </template></template>
 </section>
</template>
<style scoped>
.git-panel{margin-top:30px;padding-top:22px;border-top:1px solid #233a41}.git-form{display:grid;gap:10px;margin:18px 0}.git-form input,.git-form textarea{width:100%;padding:12px;background:#08151a;border:1px solid #29434b;color:#dcebf0;border-radius:6px}.git-form button{justify-self:start}.git-panel details{margin:14px 0}.git-file{padding:12px 0;border-bottom:1px solid #233a41}.git-file label,.git-confirm{display:flex;gap:10px;align-items:center}.git-confirm input{width:auto}.git-file code{overflow-wrap:anywhere}.git-panel pre{max-height:350px;overflow:auto;font-size:12px;background:#061015;padding:12px}
</style>
